  shell('equipe', 'Equipe', 'Administradores e analistas do painel', `<div class="panel"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>2FA</th><th>Situação</th><th>Criado em</th><th></th></tr></thead><tbody>${d.users.map((u) => `<tr><td><div class="person">${avatar(u.name, u.id)}<div><b>${esc(u.name)}</b><span>${esc(u.email)}</span></div></div></td><td>${u.role === 'admin' ? '<span class="badge info">Administrador</span>' : '<span class="badge plain">Analista</span>'}</td><td>${u.totp_enabled ? '<span class="badge ok">ativo</span>' : '<span class="badge warn">desativado</span>'}</td><td>${u.disabled ? '<span class="badge bad">desativado</span>' : '<span class="badge ok">ativo</span>'}</td><td class="sm mut">${date(u.created_at)}</td><td class="r">${u.id !== S.user.id ? `<button class="btn ghost sm" data-act="toggle" data-id="${u.id}" data-d="${u.disabled ? 0 : 1}">${u.disabled ? 'Reativar' : 'Desativar'}</button>` : '<span class="xs mut">você</span>'}</td></tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:18px"><div class="h"><h2>Matriz de permissões</h2></div><table><thead><tr><th>Recurso</th><th class="r">Administrador</th><th class="r">Analista</th><th class="r">Cliente (app)</th></tr></thead><tbody>${[['Dados próprios, empréstimos e Pix', '—', '—', '✓'], ['Aprovar empréstimos até R$ 15 mil', '✓', '✓', '—'], ['Aprovar acima de R$ 15 mil', '✓', '—', '—'], ['Cobrança, antifraude e relatórios', '✓', '✓', '—'], ['CPF completo (revelação auditada)', '✓', '—', '—'], ['Equipe, auditoria e anonimização LGPD', '✓', '—', '—']].map(([a, ...v]) => `<tr><td>${a}</td>${v.map((x) => `<td class="r" style="color:${x === '✓' ? 'var(--ok)' : 'var(--faint)'}">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`, `<button class="btn" data-act="newuser">${ico('plus')}Novo usuário</button>`);
