/* ---------- roteador e eventos globais ---------- */
async function route() {
  const h = location.hash.replace(/^#\/?/, '') || 'dashboard', [r, id] = h.split('/'); tip.hide();
  if (r === 'entrar') return P.entrar(); if (!S.token || !S.user) return (location.hash = '#/entrar');
  const map = { dashboard: P.dashboard, clientes: id ? () => P.cliente(id) : P.clientes, emprestimos: id ? () => P.emprestimo(id) : P.emprestimos, cobrancas: P.cobrancas, antifraude: P.antifraude, relatorios: P.relatorios, integracoes: P.integracoes, equipe: P.equipe, auditoria: P.auditoria };
  try { await (map[r] || P.dashboard)(); } catch (e) { if (e.status === 401) return logout(true); shell(r, 'Algo deu errado', '', `<div class="panel">${empty('Não foi possível carregar esta página', esc(e.message))}</div>`); }
  const gs = $('#gsearch'); if (gs) { let t; gs.oninput = () => { clearTimeout(t); t = setTimeout(() => { P._cf = { q: gs.value, kyc: '' }; if (gs.value.length > 1) location.hash = '#/clientes'; }, 450); }; }
}
document.addEventListener('click', (e) => {
  const go = e.target.closest('[data-go]'); if (go && !e.target.closest('button,a')) location.hash = go.dataset.go;
  const a = e.target.closest('[data-act]'); if (!a) return; const k = a.dataset.act;
  if (k === 'logout') logout(); else if (k.startsWith('export-')) download(`/api/admin/reports/${k.slice(7)}`, `lastro-${k.slice(7)}.csv`);
});
